-- pixelrp: Furni > Misc's catch-all furni go to proper categories.
--
-- Misc > More Furni's letter pages hold what 119's catch-all shelved: every
-- furniture row no page sold. Once 180 and 181 took out the duplicates and the
-- undrawable, what is left is mostly furni the catalog generator never placed
-- on purpose (gen-catalog.py classify), plus strays of lines that do have a
-- page. Each now goes where it belongs:
--
--   Builders Club furni   -> Builders > Builders Club > Shapes (one page per
--                            shape), Materials (one per material), Letters &
--                            Numbers; a new group at the end of Builders
--   promotional (ads_)    -> Furni > Promotional, open to everyone
--   a line with a page    -> that page, where it is now: Lines, Lines >
--                            Classics, Builders > Themes / Seasonal, Staff >
--                            Games / Wired / Sound / NFT / Rares / LTD, Pet Shop
--                            > Pets - a rare that sat free in Misc goes back
--                            behind the staff gate
--   anything else         -> Misc itself (test furni included, by choice)
--
-- WHERE A FURNI GOES is decided by its sprite, looked up in FurnitureData, and
-- run through gen-catalog.py's own classifier - the one that built Lines and
-- Themes in the first place, so the page captions match. The table below maps
-- 26422 sprites to 358 page paths; a path is resolved live by caption from its
-- tab, and a furni whose best path does not resolve tries the next (a Themes
-- line with no page tries More Themes; a Seasonal year with no page, its
-- holiday). Nothing resolves -> Misc.
--
-- A furni the target page already sells is deleted rather than moved in twice.
-- More Furni and its letters are deleted once empty, and so is any new page
-- that nothing landed on. Idempotent: only rows still under More Furni move,
-- and the new pages have fixed ids.

SET @furni := (SELECT `id` FROM `catalog_pages` WHERE `parent_id` = -1 AND `page_link` = 'furni' LIMIT 1);
SET @builders := (SELECT `id` FROM `catalog_pages` WHERE `parent_id` = -1 AND `caption` = 'Builders' LIMIT 1);
SET @staff := (SELECT `id` FROM `catalog_pages` WHERE `parent_id` = -1 AND `page_link` = 'staff' LIMIT 1);
SET @petshop := (SELECT `id` FROM `catalog_pages` WHERE `parent_id` = -1 AND `page_link` = 'pets_shop' LIMIT 1);
SET @misc := (SELECT `id` FROM `catalog_pages` WHERE `parent_id` = @furni AND `caption` = 'Misc' LIMIT 1);
SET @builders_last := (SELECT COALESCE(MAX(`order_num`), 0) FROM `catalog_pages` WHERE `parent_id` = @builders AND `id` NOT BETWEEN 953100 AND 953199);
SET @misc_order := (SELECT `order_num` FROM `catalog_pages` WHERE `id` = @misc);

-- 1. The new pages. Builders Club is rank 2 like the rest of Builders;
--    Promotional sits just before Misc and is open to everyone.
INSERT IGNORE INTO `catalog_pages`
