-- 2. The rows to sort: everything under Misc's pages, not on Misc itself.
DROP TABLE IF EXISTS `_ms_pages`;
CREATE TABLE `_ms_pages` (`id` INT NOT NULL PRIMARY KEY) ENGINE=InnoDB;
INSERT IGNORE INTO `_ms_pages` (`id`) SELECT `id` FROM `catalog_pages` WHERE `parent_id` = @misc;
INSERT IGNORE INTO `_ms_pages` (`id`)
    SELECT c.`id` FROM `catalog_pages` c JOIN `_ms_pages` p ON c.`parent_id` = p.`id`;
INSERT IGNORE INTO `_ms_pages` (`id`)
    SELECT c.`id` FROM `catalog_pages` c JOIN `_ms_pages` p ON c.`parent_id` = p.`id`;

