-- Each path, resolved by caption from its tab root - open pages only, which is
-- what tells the Staff tab's moved Wired from its old disabled one (930109).
UPDATE `_ms_path` x
  JOIN `catalog_pages` a ON a.`caption` = x.`p1` AND a.`visible` = b'1' AND a.`enabled` = b'1'
   AND a.`parent_id` = CASE x.`tab` WHEN 'F' THEN @furni WHEN 'B' THEN @builders WHEN 'S' THEN @staff ELSE @petshop END
  LEFT JOIN `catalog_pages` b ON x.`p2` IS NOT NULL AND b.`parent_id` = a.`id` AND b.`caption` = x.`p2`
   AND b.`visible` = b'1' AND b.`enabled` = b'1'
  LEFT JOIN `catalog_pages` c ON x.`p3` IS NOT NULL AND c.`parent_id` = b.`id` AND c.`caption` = x.`p3`
   AND c.`visible` = b'1' AND c.`enabled` = b'1'
   SET x.`page_id` = CASE
        WHEN x.`p3` IS NOT NULL THEN c.`id`
        WHEN x.`p2` IS NOT NULL THEN b.`id`
        ELSE a.`id` END;

-- 4. Each row's destination: the best path that resolved, else Misc.
DROP TABLE IF EXISTS `_ms_move`;
CREATE TABLE `_ms_move` (`id` INT NOT NULL PRIMARY KEY, `sprite_type` VARCHAR(2) NOT NULL,
    `sprite_id` INT NOT NULL, `target` INT NOT NULL) ENGINE=InnoDB;
INSERT INTO `_ms_move` (`id`, `sprite_type`, `sprite_id`, `target`)
SELECT ci.`id`, f.`type`, f.`sprite_id`,
       COALESCE((SELECT x.`page_id` FROM `_ms_map` m JOIN `_ms_path` x ON x.`path_id` = m.`path_id`
                  WHERE m.`type` = f.`type` AND m.`sprite_id` = f.`sprite_id` AND x.`page_id` IS NOT NULL
                  ORDER BY m.`priority` LIMIT 1), @misc)
  FROM `catalog_items` ci
  JOIN `_ms_pages` mp ON mp.`id` = ci.`page_id`
  JOIN `furniture` f ON CAST(f.`id` AS CHAR) = ci.`item_id`;

-- A furni its target already sells goes, rather than moving in twice.
DROP TABLE IF EXISTS `_ms_have`;
CREATE TABLE `_ms_have` (`page_id` INT NOT NULL, `type` VARCHAR(2) NOT NULL, `sprite_id` INT NOT NULL,
    PRIMARY KEY (`page_id`, `type`, `sprite_id`)) ENGINE=InnoDB;
INSERT IGNORE INTO `_ms_have` (`page_id`, `type`, `sprite_id`)
    SELECT ci.`page_id`, f.`type`, f.`sprite_id`
      FROM `catalog_items` ci JOIN `furniture` f ON CAST(f.`id` AS CHAR) = ci.`item_id`
     WHERE ci.`page_id` IN (SELECT DISTINCT `target` FROM `_ms_move`);
DELETE ci FROM `catalog_items` ci
  JOIN `_ms_move` mv ON mv.`id` = ci.`id`
  JOIN `_ms_have` h ON h.`page_id` = mv.`target` AND h.`type` = mv.`sprite_type` AND h.`sprite_id` = mv.`sprite_id`;
-- and two Misc rows of one furni bound for the same page: keep the first
DELETE ci FROM `catalog_items` ci
  JOIN `_ms_move` mv ON mv.`id` = ci.`id`
  JOIN `_ms_move` older ON older.`target` = mv.`target` AND older.`sprite_type` = mv.`sprite_type`
   AND older.`sprite_id` = mv.`sprite_id` AND older.`id` < mv.`id`;

UPDATE `catalog_items` ci JOIN `_ms_move` mv ON mv.`id` = ci.`id` SET ci.`page_id` = mv.`target`;

-- 5. Empty pages: More Furni's letters, then More Furni; and new pages nothing
--    landed on, leaves before their parents.
DELETE p FROM `catalog_pages` p
 WHERE (p.`id` IN (SELECT `id` FROM `_ms_pages`) OR p.`id` BETWEEN 953101 AND 953299)
   AND NOT EXISTS (SELECT 1 FROM `catalog_items` ci WHERE ci.`page_id` = p.`id`)
   AND NOT EXISTS (SELECT 1 FROM (SELECT `parent_id` FROM `catalog_pages`) c WHERE c.`parent_id` = p.`id`);
DELETE p FROM `catalog_pages` p
 WHERE (p.`id` IN (SELECT `id` FROM `_ms_pages`) OR p.`id` BETWEEN 953101 AND 953299)
   AND NOT EXISTS (SELECT 1 FROM `catalog_items` ci WHERE ci.`page_id` = p.`id`)
   AND NOT EXISTS (SELECT 1 FROM (SELECT `parent_id` FROM `catalog_pages`) c WHERE c.`parent_id` = p.`id`);
DELETE p FROM `catalog_pages` p
 WHERE (p.`id` IN (SELECT `id` FROM `_ms_pages`) OR p.`id` BETWEEN 953101 AND 953299)
   AND NOT EXISTS (SELECT 1 FROM `catalog_items` ci WHERE ci.`page_id` = p.`id`)
   AND NOT EXISTS (SELECT 1 FROM (SELECT `parent_id` FROM `catalog_pages`) c WHERE c.`parent_id` = p.`id`);
-- the Builders Club divider goes with its group
DELETE FROM `catalog_pages` WHERE `id` = 953100
   AND NOT EXISTS (SELECT 1 FROM (SELECT `id` FROM `catalog_pages`) c WHERE c.`id` = 953101);

DROP TABLE `_ms_have`;
DROP TABLE `_ms_move`;
DROP TABLE `_ms_map`;
DROP TABLE `_ms_path`;
DROP TABLE `_ms_pages`;
